/* -------------------------------------------------------------------------------------------------
 * Types
 * -----------------------------------------------------------------------------------------------*/

export type AgentLaneStatus = "spawning" | "running" | "waiting" | "done" | "failed" | "discarded"

export interface AgentLaneMetric {
  /** Row name in compare mode, for example "Duration" or "Tests". Keep the same order per lane. */
  label: string
  /** What to show. */
  value: React.ReactNode
  /** Number used to find the best lane for this row. */
  score?: number
  /** Which way is better. Default "lower". */
  better?: "lower" | "higher"
}

export interface AgentLane {
  id: string
  /** Lane name: an attempt, a model or a persona. */
  name: string
  /** One or two characters that identify the lane without color. Defaults to the name's first. */
  monogram?: string
  /** The approach in a few words, under the name. */
  description?: string
  status: AgentLaneStatus
  /** What the agent is doing now. One line, crossfades on change. */
  step?: React.ReactNode
  /** The lane's answer. Strings render as text with fenced code blocks; nodes render as is. */
  output?: React.ReactNode
  /** Why it failed, and what to try. */
  error?: React.ReactNode
  startedAt?: number
  durationMs?: number
  metrics?: AgentLaneMetric[]
}

/* -------------------------------------------------------------------------------------------------
 * AgentLanes
 * -----------------------------------------------------------------------------------------------*/

export interface AgentLanesProps extends Omit<React.ComponentProps<"section">, "title"> {
  /** Two to four lanes. More scroll sideways. */
  lanes: AgentLane[]
  title?: React.ReactNode
  /** Chosen lane. Others dim to Discarded. */
  winnerId?: string
  onPick?: (id: string) => void
  /** Shows Undo on the chosen lane. */
  onUndoPick?: () => void
  /** Shows Retry on failed lanes, in place of the pick. Receives the lane id. */
  onRetry?: (id: string) => void
  compare?: boolean
  defaultCompare?: boolean
  onCompareChange?: (compare: boolean) => void
  /** Lane height. Outputs scroll inside. Default 26rem. */
  laneHeight?: number | string
}

/** Best score per metric row across lanes. Ties all count as best. */
function bestByRow(lanes: AgentLane[]) {
  const rows = new Map<string, number>()
  for (const lane of lanes) {
    if (lane.status === "failed") continue
    for (const m of lane.metrics ?? []) {
      if (m.score === undefined) continue
      const prev = rows.get(m.label)
      const higher = m.better === "higher"
      if (prev === undefined || (higher ? m.score > prev : m.score < prev))
        rows.set(m.label, m.score)
    }
  }
  return rows
}

const isActive = (s: AgentLaneStatus) => s === "spawning" || s === "running" || s === "waiting"

type ButtonVariant = "solid" | "outline" | "ghost" | "subtle"

type ButtonSize = "xs" | "sm" | "md" | "lg" | "icon-xs" | "icon-sm" | "icon-md" | "icon-lg"

