        return code ? (
          <pre
            key={i}
            className="rounded-(--chatcn-radius-md) bg-(color:--chatcn-inset) text-[0.75rem]/[1rem] text-(color:--chatcn-fg-muted) my-2 px-3 py-2 font-mono [overflow-wrap:anywhere] whitespace-pre-wrap"
