            ))}
          </span>
        ) : (
          <span className="flex-1" />
        )}
        {isWinner ? (
          onUndo ? (
            <Button size="sm" onClick={onUndo}>
              <Undo2Icon />
              Undo
            </Button>
          ) : null
        ) : lane.status === "failed" && onRetry && !decided ? (
          // A failed lane offers its retry in place of the pick it can no longer win.
          <Button
            size="sm"
            variant="outline"
            onClick={() => onRetry(lane.id)}
            aria-describedby={titleId}
            className="pointer-coarse:h-11"
          >
            <RotateCcwIcon />
            Retry
          </Button>
        ) : onPick && !decided ? (
          <Button
            size="sm"
            variant="outline"
            disabled={lane.status !== "done"}
            onClick={() => onPick(lane.id)}
            aria-describedby={titleId}
            className="pointer-coarse:h-11"
          >
            Use this one
          </Button>
        ) : null}
      </footer>
    </article>
  )
}

/**
 * Parallel agents side by side: two to four lanes, each with a monogram, status, the step it is
 * on and its streaming output. Compare lines up the metrics and marks the best value per row.
 * Use this one picks a winner; the others dim, and Undo takes it back.
 */
export function AgentLanes({
  lanes,
  title,
  winnerId,
  onPick,
  onUndoPick,
  onRetry,
  compare: compareProp,
  defaultCompare = false,
  onCompareChange,
  laneHeight = "26rem",
  className,
  ...props
}: AgentLanesProps) {
  const [compareState, setCompareState] = React.useState(defaultCompare)
  const compare = compareProp ?? compareState
  const setCompare = (next: boolean) => {
    if (compareProp === undefined) setCompareState(next)
    onCompareChange?.(next)
  }
  const best = React.useMemo(() => bestByRow(lanes), [lanes])
  const done = lanes.filter((l) => l.status === "done").length
  const running = lanes.filter((l) => isActive(l.status)).length
  const failed = lanes.filter((l) => l.status === "failed").length
  const hasMetrics = lanes.some((l) => l.metrics?.length)
  const headingId = React.useId()
  const cols = Math.min(4, Math.max(1, lanes.length))

  return (
    <section
      aria-labelledby={headingId}
      data-slot="agent-lanes"
      className={cn("flex min-w-0 flex-col gap-3", className)}
      {...props}
    >
      <header className="flex min-w-0 flex-wrap items-center gap-x-3 gap-y-2">
        <h2 id={headingId} className="text-[0.875rem]/[1.25rem] tracking-[-0.003em] text-(color:--chatcn-fg) font-medium">
          {title ?? `${lanes.length} agents in parallel`}
        </h2>
        <p className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) me-auto tabular-nums" aria-live="polite">
          {[
            running ? `${running} running` : null,
            done ? `${done} done` : null,
            failed ? `${failed} failed` : null,
          ]
            .filter(Boolean)
            .join(" · ")}
        </p>
        {hasMetrics ? (
          <Button
            size="sm"
            aria-pressed={compare}
            onClick={() => setCompare(!compare)}
            className={cn(compare && "bg-(color:--chatcn-fill) text-(color:--chatcn-fg)")}
          >
            <Columns3Icon />
            Compare
          </Button>
        ) : null}
      </header>

      <div
        data-slot="agent-lanes-grid"
        className="chatcn-scroll relative -mx-1 grid snap-x snap-mandatory auto-cols-[minmax(17rem,1fr)] grid-flow-col gap-2 overflow-x-auto px-1 pb-1"
        style={{ gridTemplateColumns: `repeat(${cols}, minmax(17rem, 1fr))` }}
      >
        {lanes.map((lane) => (
          <Lane
            key={lane.id}
            lane={lane}
            compare={compare}
            best={best}
            winnerId={winnerId}
            onPick={onPick}
            onUndo={onUndoPick}
            onRetry={onRetry}
            height={laneHeight}
          />
        ))}
      </div>
    </section>
  )
}

export default AgentLanes

